export function buildCollisionGrid(world){world.colliders=world.buildings.map(b=>({x:b.x,z:b.z,w:b.w,d:b.d}));return world.colliders}
export function moveBodyWithCollisions(body,dx,dz,world){let nx=body.x+dx,nz=body.z+dz;if(nx<world.limits.minX+8||nx>world.limits.maxX-8)nx=body.x;if(nz<world.limits.minZ+8||nz>world.limits.maxZ-8)nz=body.z;for(const c of world.colliders||[]){if(Math.abs(nx-c.x)<c.w/2+5&&Math.abs(nz-c.z)<c.d/2+5){nx=body.x;nz=body.z;break}}body.x=nx;body.z=nz;return body}
export function queryLineOfSight(a,b,world){for(const c of world.colliders||[]){const t=((c.x-a.x)*(b.x-a.x)+(c.z-a.z)*(b.z-a.z))/((b.x-a.x)**2+(b.z-a.z)**2||1);if(t>0&&t<1){const x=a.x+(b.x-a.x)*t,z=a.z+(b.z-a.z)*t;if(Math.abs(x-c.x)<c.w/2&&Math.abs(z-c.z)<c.d/2)return false}}return true}
